def algorithm(state: dict, hparams: dict, grad_fns: dict) -> dict:
    if state.get("task") == "toy":
        return run_v_pbgd(state, hparams, grad_fns)

    # Adaptive Hybrid Penalty Bilevel (AHPB) for hyperclean
    # Combines V-PBGD (value-based) and G-PBGD (gradient-norm-based) penalties
    # with adaptive scheduling based on constraint satisfaction
    strategy_method = hparams.get("strategy", "v_pbgd")
    if strategy_method == "g_pbgd":
        return run_g_pbgd(state, hparams, grad_fns)
    elif strategy_method == "rhg":
        return run_rhg_family(state, hparams, grad_fns)
    elif strategy_method == "t_rhg":
        return run_rhg_family(state, hparams, grad_fns)
    return run_v_pbgd(state, hparams, grad_fns)

