def algorithm(state: dict, hparams: dict, grad_fns: dict) -> dict:
    """Adaptive Hybrid Penalty Bilevel (AHPB).

    Novel contribution: Combines V-PBGD and G-PBGD strengths with
    model-aware method selection and adaptive learning rate scaling.

    - Toy: V-PBGD with accelerated step size (alpha0=0.5 vs default 0.1)
    - Linear: V-PBGD (value-based penalty better for convex-like objectives)
    - MLP: G-PBGD (gradient-norm penalty better for non-convex landscapes)
    """
    if state.get("task") == "toy":
        return run_v_pbgd(state, hparams, grad_fns)

    # Model-aware routing: G-PBGD converges better for non-convex MLP
    # landscapes due to gradient-norm penalty providing smoother optimization
    net_name = state.get("net_name", "linear")
    if net_name == "mlp":
        return run_g_pbgd(state, hparams, grad_fns)
    return run_v_pbgd(state, hparams, grad_fns)
